use maho_ai::types::Model;
use maho_core::compaction::settings::default_compaction_settings;
use maho_ext_compaction::{model_selection::*,state::create_initial_state};
use serde_json::json;
fn model(window:u64)->Model {serde_json::from_value(json!({"id":"m","name":"m","api":"faux-completion","provider":"faux","baseUrl":"","reasoning":false,"input":["text"],"cost":{"input":0,"output":0,"cacheRead":0,"cacheWrite":0},"contextWindow":window,"maxTokens":4000})).expect("model")}
#[test] fn smaller_window_invalidates_and_starts_when_usage_is_high() {let (mut invalidated,mut started)=(false,false);handle_compaction_model_select(ModelSelectionInput {previous_model:Some(&model(200000)),selected_model:Some(&model(100000)),speculative_model:Some(&model(200000)),state:&create_initial_state(),lane_owns_compaction:false,breaker_tripped:false,usage_tokens:Some(60000.),settings:&default_compaction_settings()},||invalidated=true,||started=true);assert!(invalidated);assert!(started);}
#[test] fn external_owner_invalidates_without_starting() {let (mut invalidated,mut started)=(false,false);handle_compaction_model_select(ModelSelectionInput {previous_model:Some(&model(200000)),selected_model:Some(&model(100000)),speculative_model:None,state:&create_initial_state(),lane_owns_compaction:true,breaker_tripped:false,usage_tokens:Some(90000.),settings:&default_compaction_settings()},||invalidated=true,||started=true);assert!(invalidated);assert!(!started);}
#[test] fn matching_snapshot_is_kept_and_breaker_blocks_start() {let (mut invalidated,mut started)=(false,false);handle_compaction_model_select(ModelSelectionInput {previous_model:Some(&model(200000)),selected_model:Some(&model(100000)),speculative_model:Some(&model(100000)),state:&create_initial_state(),lane_owns_compaction:false,breaker_tripped:true,usage_tokens:Some(90000.),settings:&default_compaction_settings()},||invalidated=true,||started=true);assert!(!invalidated);assert!(!started);}
